import networkx as nx
G = nx.Graph()
for i in range(30):
    G.add_node(i)
for i in range(30):
    for j in range(i+1, 30):
        if (j-i) % 7 == 0:
            G.add_edge(i, j)
if nx.girth(G) >= 7 and nx.is_colorable(G, 3) and G.number_of_edges() >= 33:
    print("SATISFIABLE")
    print(list(G.edges))
else:
    print("UNSATISFIABLE")
